"""Frozen prompts for the LOULA_DICE_RECOGNITION pilot (handoff sections 4 and 7).

GEN is imported from Experiment 21 so the generation instruction is byte-identical to its G prompt.
"""

from __future__ import annotations

import hashlib
import re

from spar_dynamic.dice_logprob.prompts import GEN
from spar_dynamic.dice_recognition import config as C

J_SELF = ("Two sequences were generated by different language models. Each model was given the same instruction:\n\n"
          + GEN + "\n\n"
          "Both models used sampling temperature 0.7. One sequence was generated by another instance of your model, "
          "and the other by a different language model.\n\n"
          "Sequence A: {sequence_A}\nSequence B: {sequence_B}\n\n"
          "Which sequence was generated by an instance of your model? Answer A or B only.")

J_NAMED = ("Two sequences were generated by different language models: Qwen3-32B and Mistral Small 3.2 24B. "
           "Each model was given the same instruction:\n\n"
           + GEN + "\n\n"
           "Both models used sampling temperature 0.7.\n\n"
           "Sequence A: {sequence_A}\nSequence B: {sequence_B}\n\n"
           "Which sequence was generated by {TARGET_MODEL}? Answer A or B only.")

TARGET_NAMES = {"qwen": "Qwen3-32B", "mistral": "Mistral Small 3.2 24B"}
CONDITIONS = ("self", "named_qwen", "named_mistral")

_SEQ_RE = re.compile(r"[1-6]( [1-6]){9}")


def sha256(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8")).hexdigest()


def generation_prompt() -> str:
    return GEN


def judgment_prompt(condition: str, seq_a: str, seq_b: str) -> str:
    assert _SEQ_RE.fullmatch(seq_a) and _SEQ_RE.fullmatch(seq_b)
    if condition == "self":
        return J_SELF.format(sequence_A=seq_a, sequence_B=seq_b)
    target = condition.split("_", 1)[1]
    return J_NAMED.replace("{TARGET_MODEL}", TARGET_NAMES[target]).format(sequence_A=seq_a, sequence_B=seq_b)


def parse_sequence(text):
    """Strict: exactly ten integers 1-6 separated by single ASCII spaces, nothing else (no strip)."""
    if text is None or not _SEQ_RE.fullmatch(text):
        return None
    return [int(x) for x in text.split(" ")]


def parse_choice(text):
    """Strict A/B: the whole response must be 'A' or 'B' (surrounding whitespace allowed, nothing else)."""
    if text is None:
        return None
    t = text.strip()
    return t if t in ("A", "B") else None


def render_frozen() -> str:
    ex_a, ex_b = "{sequence_A}", "{sequence_B}"
    parts = [f"# {C.TAG}: frozen prompts\n\nOne user message per call, empty history, no system message, no tools.\n",
             f"\n## Generation (both models; identical to Experiment 21's G)\n\nsha256 `{sha256(GEN)}`\n\n```text\n{GEN}\n```\n",
             f"\n## J_self template (both judges)\n\nsha256 `{sha256(J_SELF)}`\n\n```text\n{J_SELF}\n```\n",
             f"\n## J_named template\n\nsha256 `{sha256(J_NAMED)}`; TARGET_MODEL is exactly `Qwen3-32B` or `Mistral Small 3.2 24B`.\n\n```text\n{J_NAMED}\n```\n"]
    return "".join(parts)
